input.command:
cd /work; psql -q -v ON_ERROR_STOP=1 <<'EOF'
create temp table pa as select (select min(product_id) from products where category='SOFTWARE') s,(select min(product_id) from products where category='HARDWARE') h;
insert into orders values (900001,(select min(customer_id) from customers),'2031-03-15 12:00+00','COMPLETED',0),(900002,(select min(customer_id) from customers),'2031-03-16 12:00+00','COMPLETED',0);
-- order 900001: first line (lowest id) HARDWARE qty 2 @10, second SOFTWARE qty 5 @100, inserted in reverse physical order
insert into order_items select 900102,900001,s,5,100 from pa;
insert into order_items select 900101,900001,h,2,10 from pa;
EOF
psql -q -v ON_ERROR_STOP=1 -f etl.sql; echo etl_rc=$?
psql -c "select * from dash_revenue_by_category where month='2031-03'" -c "select source_order_count,loaded_order_count,mismatch from etl_run_log order by run_id desc limit 1"
psql -q <<'EOF'
delete from order_items where order_id in (900001,900002);
delete from orders where order_id in (900001,900002);
EOF
psql -q -v ON_ERROR_STOP=1 -f etl.sql; psql -c "select source_order_count,loaded_order_count,mismatch from etl_run_log order by run_id desc limit 1" -c "select count(*) from dash_revenue_by_category where month='2031-03'"

